function initGeo(){if(!window.L||geoMap||geoState==='fallback')return;try{geoState='loading';geoMap=L.map('geoMap',{scrollWheelZoom:false}).setView([-6.3650,106.8265],15);geoMarkers=L.layerGroup().addTo(geoMap);const tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,referrerPolicy:'strict-origin-when-cross-origin',attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'});geoTiles=tiles;tiles.on('tileerror',()=>coordinateFallback('Peta jalan gagal dimuat. Titik koordinat dan petunjuk arah tetap tersedia.'));tiles.on('load',()=>{if(geoState!=='loading')return;clearTimeout(geoTimer);geoState='ready';$('geoMap').style.visibility='visible';$('geoFallback').hidden=true;renderGeo();});geoTimer=setTimeout(()=>coordinateFallback('Peta jalan tidak merespons. Gunakan titik koordinat atau buka peta asli.'),12000);tiles.addTo(geoMap);renderGeo(true);}catch(e){coordinateFallback('Peta jalan tidak tersedia. Gunakan titik koordinat atau buka peta asli.');console.warn('Peta geografis tidak tersedia:',e.message);}}
