function renderGeo(fit=false){const zs=visible().filter(hasCoords);renderCoordinateMap();$('geoMessage').hidden=geoState!=='ready';$('geoMessage').textContent=zs.length?`${zs.length} zona berkoordinat · ${vehicle} · ${dataLabel()}`:'Tidak ada koordinat tercatat untuk pilihan ini.';if(!geoMap||geoState==='fallback')return;if(userCoords&&!userGeoMarker)userGeoMarker=L.circleMarker([userCoords.lat,userCoords.lng],{radius:7,color:'#fff',fillColor:'#2774a6',fillOpacity:1,weight:2}).addTo(geoMap).bindTooltip('Lokasi perangkat');const signature=JSON.stringify(zs.map(z=>[z.id,z.name,z.faculty,z.lat,z.lng,get(z).status,get(z).free,selected===z.id]));if(signature!==lastGeoSignature){lastGeoSignature=signature;geoMarkers.clearLayers();zs.forEach(z=>{const d=get(z),icon=L.divIcon({className:'geo-icon',html:`<span aria-hidden="true" class="geo-pin ${d.status} ${selected===z.id?'selected':''}">${esc(markerLabel(z))}</span>`,iconSize:[markerWidth(z),32],iconAnchor:[markerWidth(z)/2,16]});const m=L.marker([z.lat,z.lng],{icon,title:markerTitle(z),alt:markerTitle(z),keyboard:true,zIndexOffset:selected===z.id?1000:0}).addTo(geoMarkers);m.bindTooltip(esc(markerTitle(z)));m.on('click',()=>{selected=z.id;renderMap();renderZones();window.ParkSenseMobile?.openDetail();});});}if(fit){geoMap.invalidateSize();if(zs.length)geoMap.fitBounds(zs.map(z=>[z.lat,z.lng]),{padding:[30,30],maxZoom:17,animate:false});else geoMap.setView([-6.3650,106.8265],15,{animate:false});}}
function renderMap(){const zones=visible(),preferred=zones.filter(hasCoords);if(!zones.some(z=>z.id===selected))selected=preferred[0]?.id||zones[0]?.id||'';$('mapDetail').innerHTML=detailHTML(zones.find(z=>z.id===selected));$('mapDetail').querySelector('[data-save]')?.addEventListener('click',e=>toggleSaved(e.currentTarget.dataset.save));syncVehicle();renderGeo();window.ParkSenseMobile?.update();}
function renderZones(){if(document.body.classList.contains('data-loading54')){$('zoneGrid').innerHTML=Array.from({length:3},()=>'<div class="skeleton-zone54" aria-hidden="true"><i></i><span><i></i><i></i></span><span><i></i><i></i></span></div>').join('');$('resultText').textContent='Memuat daftar zona…';return;}if(document.body.classList.contains('data-unavailable')){$('zoneGrid').innerHTML='<div class="empty">Data zona belum tersedia. Segarkan data ketika koneksi kembali.</div>';$('resultText').textContent='Data belum tersedia';return;}const zs=visible();const displayed=showAll?zs:zs.slice(0,3);$('zoneGrid').innerHTML=displayed.length?displayed.map(z=>{const d=get(z),known=d.free!==null,pct=known?Math.min(100,Math.round(d.occupied/d.cap*100)):null;return `<button class="zone-card zone-long ${selected===z.id?'selected':''}" data-zone="${esc(z.id)}"><span class="zone-image"><img src="${esc(photoByZone[z.id]||'assets/parking-illustration.svg')}" alt="${photoByZone[z.id]?'Foto '+esc(z.name):'Ilustrasi parkiran sementara'}" loading="lazy" decoding="async"><span class="zone-image-caption">${photoByZone[z.id]?'Foto zona':'Ilustrasi · foto belum tersedia'}</span></span><span class="zone-info"><span class="zone-identity"><span class="zone-head">${logo(z.faculty)}<span><strong class="zone-title">${esc(z.name)}</strong><small>${esc(faculty(z.faculty).name)} · ${vehicle==='motor'?'Motor':'Mobil'}</small></span></span><span class="zone-status-line">${status(d.status)}<span class="zone-demo-label">${liveMode?'DATA PUBLIK':snapshotMode?'SNAPSHOT · BUKAN LIVE':'DATA TRIAL'}</span></span></span><span class="zone-stat-area"><span class="zone-metrics"><span><small>Kapasitas${z.estimated?.includes(vehicle)?' (est.)':''}</small><strong class="${d.cap===null?'unknown':''}">${d.cap===null?'Belum diisi':num(d.cap)}</strong></span><span><small>Terisi</small><strong>${known?num(d.occupied):'—'}</strong></span><span><small>Slot kosong</small><strong class="zone-free ${known?'':'unknown'}">${known?num(d.free):'Belum dihitung'}</strong></span></span>${known?`<span class="zone-progress" role="img" aria-label="Keterisian ${dataLabel()} ${pct}%"><span style="width:${pct}%"></span></span>`:'<span class="zone-unknown-note slim-sr-only">Jumlah terisi dan slot kosong belum diketahui.</span>'}</span><span class="zone-footer"><span class="slim-sr-only">${db.saved.includes(z.id)?'★ Lokasi tersimpan · ':''}Lihat detail di peta</span><span class="zone-arrow" aria-hidden="true">↗</span></span></span></button>`}).join(''):`<div class="empty">Tidak ada zona yang cocok. ${facultyFilter?'Coba kendaraan lain atau hapus filter.':''}</div>`;$('resultText').textContent=`${displayed.length} dari ${zs.length} zona · ${facultyFilter?faculty(facultyFilter).name+' · ':''}${vehicle==='motor'?'Motor':'Mobil'} · ${dataLabel()}`; $('showAll').textContent=showAll?'Ringkas daftar ↑':'Lihat semua zona →';$$('[data-zone]').forEach(b=>b.onclick=()=>{selected=b.dataset.zone;const z=db.zones.find(z=>z.id===selected);renderMap();if(geoMap&&geoState!=='fallback'&&hasCoords(z))geoMap.panTo([z.lat,z.lng]);renderZones();if(!window.ParkSenseMobile?.openDetail())navTo('peta')});}
function validNewsPhoto(p){return typeof p==='string'&&/^data:image\/(?:jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(p)&&p.length<1000000;}
function newsPhoto(n){const real=validNewsPhoto(n.photo)||(liveMode&&typeof n.photo==='string'&&n.photo.startsWith(window.ParkSensePublic.photoPrefix()));return `<div class="news-photo"><img src="${real?esc(n.photo):'assets/parking-illustration.svg'}" alt="${real?'Foto pendukung pengumuman':'Ilustrasi area parkir sementara'}" loading="lazy" decoding="async"><span>${real?'Foto pendukung':'Ilustrasi · foto belum tersedia'}</span></div>`;}
function renderNews(){if(document.body.classList.contains('data-loading54')){$('newsGrid').innerHTML='<div class="skeleton-news54" aria-hidden="true"><i></i><span><i></i><i></i></span></div><p class="meta">Memuat berita parkir…</p>';return;}if(document.body.classList.contains('data-unavailable')){$('newsGrid').innerHTML='<div class="news-empty"><strong>Berita belum dapat dimuat</strong></div>';return;}if(publicNewsError56){$('newsGrid').innerHTML='<div class="news-empty"><strong>Berita belum dapat dimuat</strong><p>Coba segarkan data. Ini bukan berarti belum ada berita.</p></div>';return;}const published=db.news.filter(n=>n.published);$('newsGrid').innerHTML=published.length?published.map(n=>`<article class="news-card news-article">${newsPhoto(n)}<div class="news-body"><small>${esc(n.category||'Pengumuman parkir · Demo')}${n.date?' · '+esc(n.date):''}</small><h3>${esc(n.title)}</h3><p class="news-summary">${esc(n.summary||n.body)}</p><p class="meta">${esc(faculty(n.faculty).name)}</p><button type="button" class="text-btn" data-read-news="${esc(n.id)}">Baca selengkapnya <span aria-hidden="true">↗</span></button></div></article>`).join(''):`<div class="news-empty"><strong>Belum ada berita parkir diterbitkan</strong><p>${snapshotMode?'Tidak ada berita terbit yang tersedia.':'Pengumuman terbit dari petugas demo akan langsung muncul di sini.'}</p></div>`;$$('[data-read-news]').forEach(b=>b.onclick=()=>{const n=db.news.find(n=>n.id===b.dataset.readNews&&n.published);if(n)dialog(n.title,`${newsPhoto(n)}<p><strong>${esc(faculty(n.faculty).name)} · Pengumuman ${dataLabel()}</strong></p><p style="white-space:pre-wrap">${esc(n.body)}</p>`)});}
async function processNewsPhoto(file){if(!file||!file.size)return null;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024)throw Error('Pilih JPG, PNG atau WebP maksimal 5 MB.');const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();const ratio=Math.min(1,1000/img.width,650/img.height);const c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.width*ratio));c.height=Math.max(1,Math.round(img.height*ratio));const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(img,0,0,c.width,c.height);const data=c.toDataURL('image/jpeg',.78);if(!validNewsPhoto(data))throw Error('Foto terlalu besar setelah diproses.');return data;}finally{URL.revokeObjectURL(url);}}

function renderGuest(fitMap=true){window.ParkSenseSignature?.syncBusy();renderFaculties();$$('[data-vehicle]').forEach(b=>{const a=b.dataset.vehicle===vehicle;b.classList.toggle('active',a);b.setAttribute('aria-pressed',a)});$$('[data-status]').forEach(b=>{const a=b.dataset.status===filter;b.classList.toggle('active',a);b.setAttribute('aria-pressed',a)});$('clearFilter').hidden=!(facultyFilter||query||filter!=='all'||savedOnly);renderMap();renderZones();renderSummary();searchHint56();renderNews();if(fitMap&&geoMap)renderGeo(true);$('suggestions').innerHTML=[...faculties.flatMap(f=>[f.code,f.name]),...db.zones.map(z=>z.name)].map(x=>`<option value="${esc(x)}"></option>`).join('');if(snapshotMode){$('mapDetail').querySelectorAll('[data-save]').forEach(b=>{b.disabled=true;b.textContent='Simpan lokasi belum tersedia';});$('savedOnly').disabled=true;}}
function dialog(title,body){$('dialogTitle').textContent=title;$('dialogBody').innerHTML=body;if(!$('infoDialog').open)$('infoDialog').showModal()}
function realMap(){const zs=eligible().filter(z=>z.lat!=null);const z=zs.find(z=>z.id===selected)||zs[0];if(!z){dialog('Peta geografis','<p>Belum ada koordinat terverifikasi untuk pilihan ini pada katalog trial. Gunakan FEB atau FMIPA.</p>');return}const bbox=[106.821,-6.373,106.831,-6.356].join('%2C');dialog('Peta geografis · OpenStreetMap',`<p style="font-size:12px">Peta asli di bawah memerlukan internet. Penanda awal: ${esc(z.name)}. Pilih tautan zona untuk membuka lokasi aktual yang tercatat; peta ilustrasi sebelumnya bukan petunjuk arah.</p><div class="real-map"><iframe title="Peta OpenStreetMap" loading="lazy" decoding="async" src="https://www.openstreetmap.org/export/embed.html?bbox=${bbox}&amp;layer=mapnik&amp;marker=${z.lat}%2C${z.lng}"></iframe></div><div class="real-links">${zs.map(a=>`<a href="https://www.openstreetmap.org/?mlat=${a.lat}&amp;mlon=${a.lng}#map=18/${a.lat}/${a.lng}" target="_blank" rel="noopener noreferrer">${esc(a.name)} ↗</a>`).join('')}</div><p style="font-size:10px">© OpenStreetMap contributors · Titik lokasi berdasarkan katalog proyek. Jika peta tidak muncul, buka salah satu tautan di atas.</p>`)}
let opsQuery='',opsStatus='all',opsHistoryQuery='',opsHistoryMore=false;
function log(action,extra={}){db.history.unshift({id:globalThis.crypto?.randomUUID?.()||String(Date.now())+'-'+Math.random(),faculty:adminFaculty,action,time:new Date().toISOString(),...extra});db.history=db.history.slice(0,80)}
function canUndoCount(){const h=db.history[0];if(!h||h.faculty!==adminFaculty||h.kind!=='count')return false;const z=db.zones.find(z=>z.id===h.zone&&z.faculty===adminFaculty);return !!z&&z.occupied[h.vehicle]===h.after&&z.capacity[h.vehicle]>=h.before;}
function undoLastCount(){if(!canUndoCount()){toast('Catatan terakhir tidak dapat dibatalkan.');return;}const h=db.history[0],z=db.zones.find(z=>z.id===h.zone);if(!confirm('Batalkan catatan kendaraan terakhir untuk '+z.name+'?'))return;z.occupied[h.vehicle]=h.before;z.updatedAt=new Date().toISOString();log('Koreksi catatan: '+z.name+' · '+h.after+' → '+h.before,{kind:'correction',ref:h.id});save();toast('Koreksi simulasi dicatat.');}
function opsDate(iso){if(!iso)return 'Belum ada pembaruan';const d=new Date(iso);return Number.isFinite(d.getTime())?d.toLocaleString('id-ID',{timeZone:'Asia/Jakarta',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})+' WIB':'—';}
function opsHistory(){const all=db.history.filter(h=>h.faculty===adminFaculty&&h.action.toLowerCase().includes(opsHistoryQuery.toLowerCase()));$('history').innerHTML=all.length?all.slice(0,opsHistoryMore?80:8).map(h=>`<div class="history-row"><span>${esc(h.action)}</span><small>${esc(opsDate(h.time))}</small></div>`).join(''):'<p class="meta">'+(opsHistoryQuery?'Tidak ada aktivitas yang cocok.':'Belum ada aktivitas.')+'</p>';$('opsHistoryMore').hidden=all.length<=8;$('opsHistoryMore').textContent=opsHistoryMore?'Tampilkan lebih sedikit':'Lihat seluruh riwayat ('+all.length+')';}

function changeCount(id,v,delta){const z=db.zones.find(z=>z.id===id&&z.faculty===adminFaculty);if(!z||!['motor','mobil'].includes(v)||![-1,1].includes(delta)||!Number.isInteger(z.occupied[v]))return;const before=z.occupied[v],next=before+delta;if(next<0||next>z.capacity[v]){toast('Jumlah di luar batas kapasitas.');return}z.occupied[v]=next;z.updatedAt=new Date().toISOString();log(`${z.name} · ${v} ${delta>0?'masuk':'keluar'} · ${before} → ${next}`,{kind:'count',zone:id,vehicle:v,before,after:next});save();toast('Perubahan demo tersimpan lokal.')}
function openAdmin(){if(liveMode){window.ParkSenseLiveOps?.open();return;}if(snapshotMode){toast('Ruang petugas belum tersedia. Segarkan koneksi data publik terlebih dahulu.');return;}if($('facultyDialog').open)$('facultyDialog').close();if($('infoDialog').open)$('infoDialog').close();$('guest').hidden=true;$('admin').hidden=false;document.body.classList.add('ops-open');$$('.dock a').forEach(a=>a.classList.remove('active'));$$('[data-open-admin]').forEach(b=>b.classList.add('active'));$('adminFaculty').value=adminFaculty;renderAdmin();window.scrollTo({top:0,behavior:'auto'})}
