// Follow the actual document order, not an independently maintained menu order.
let scrollQueued=false,navIntent=null;
const menuAlias={lokasi:'peta'};
function clearNavIntent(){navIntent=null;queueNav();}
window.addEventListener('wheel',clearNavIntent,{passive:true});
window.addEventListener('touchstart',clearNavIntent,{passive:true});
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','PageUp','PageDown','Home','End',' '].includes(e.key)&&!e.target.closest('input,textarea,select,button,[contenteditable]'))clearNavIntent();});
window.addEventListener('pointerdown',e=>{if(e.clientX>=document.documentElement.clientWidth)clearNavIntent();},{passive:true});
function updateNav(){
 scrollQueued=false;if(!$('admin').hidden)return;
 const header=document.querySelector('.header');
 const offset=header.getBoundingClientRect().bottom+Math.min(70,innerHeight*.12);
 const sections=[...document.querySelectorAll('#guest section[id],#guest footer[id]')].filter(el=>['beranda','fakultas','peta','lokasi','info','bantuan','tentang'].includes(el.id));
 let active='beranda';
 for(const el of sections){if(el.getBoundingClientRect().top<=offset)active=el.id;}
 const maxScroll=Math.max(0,document.documentElement.scrollHeight-innerHeight);
 const atBottom=maxScroll>0&&scrollY>=maxScroll-4;
 if(atBottom)active='tentang';
 // Info and Tentang can share the same clamped scroll destination at the page end.
 // Honour an explicit menu click there; manual scrolling clears the intent.
 if(navIntent){
  const target=$(navIntent),padding=parseFloat(getComputedStyle(document.documentElement).scrollPaddingTop)||0;
  const targetY=target?Math.max(0,Math.min(maxScroll,scrollY+target.getBoundingClientRect().top-padding)):NaN;
  if(Math.abs(scrollY-targetY)<=5)active=navIntent;
 }
 active=menuAlias[active]||active;
 $$('.nav-links a,.dock a').forEach(a=>{
  const match=a.getAttribute('href')==='#'+(a.closest('.dock')&&['bantuan','tentang'].includes(active)?'info':active);
  a.classList.toggle('active',match);if(match)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');
 });
 window.ParkSenseMobile?.setActive(active);
 const links=$('navLinks'),a=links.querySelector('a.active');
 if(a&&a.offsetWidth){links.style.setProperty('--nav-x',a.offsetLeft+'px');links.style.setProperty('--nav-w',a.offsetWidth+'px');links.classList.add('ready');}
}

function queueNav(){if(!scrollQueued){scrollQueued=true;requestAnimationFrame(updateNav);}}window.addEventListener('scroll',queueNav,{passive:true});window.addEventListener('resize',queueNav);document.fonts?.ready.then(queueNav);


